CREATE TABLE `pinners` (
  `username` VARCHAR(190),
  `full_name` TEXT,
  `website_url` TEXT,
  `domain_url` TEXT,
  `contact_email` VARCHAR(255),
  `contact_phone` VARCHAR(64),
  `image_url` TEXT,
  `board_count` BIGINT,
  `follower_count` BIGINT,
  `following_count` BIGINT,
  `pin_count` BIGINT,
  `profile_reach` BIGINT,
  `profile_views` BIGINT,
  `last_pin_at` VARCHAR(64),
  PRIMARY KEY (`username`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `boards` (
  `id` VARCHAR(64),
  `name` TEXT,
  `description` TEXT,
  `url` TEXT,
  `image_cover_url` TEXT,
  `follower_count` BIGINT,
  `section_count` BIGINT,
  `pin_count` BIGINT,
  `category` VARCHAR(190),
  `privacy` VARCHAR(64),
  `modified_at` VARCHAR(64),
  `owner_username` VARCHAR(190),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `pins` (
  `id` VARCHAR(64),
  `title` TEXT,
  `description` TEXT,
  `link` TEXT,
  `pin_url` TEXT,
  `image` TEXT,
  `saves` BIGINT,
